import Foundation

/// Offline mnemonic construction. Acronyms and chunking are fully automatic; the other
/// kinds are authored by the learner or generated by the AI coach.
enum MnemonicGenerator {
    static func acronym(for item: LearningItem) -> Mnemonic? {
        let points = item.gradingPoints
        guard points.count >= 2 else { return nil }
        let letters = points.compactMap { point -> String? in
            let words = point.split(separator: " ").map(String.init)
            let word = words.first { !TextNormalizer.isStopword(TextNormalizer.normalize($0)) } ?? words.first
            return word?.first.map { String($0).uppercased() }
        }
        guard letters.count >= 2 else { return nil }
        let expansion = zip(letters, points).map { "\($0) → \($1)" }.joined(separator: "\n")
        return Mnemonic(kind: .acronym, content: letters.joined(separator: " "), explanation: expansion, origin: .local)
    }

    static func chunking(for item: LearningItem) -> Mnemonic? {
        let source = item.answer
        let digits = source.filter(\.isNumber)
        if digits.count >= 6 {
            let chunks = stride(from: 0, to: digits.count, by: 3).map { start -> String in
                let s = digits.index(digits.startIndex, offsetBy: start)
                let e = digits.index(s, offsetBy: min(3, digits.count - start))
                return String(digits[s..<e])
            }
            return Mnemonic(kind: .chunking, content: chunks.joined(separator: " · "),
                            explanation: L("mnemonic.chunking.digits"), origin: .local)
        }
        let points = item.gradingPoints
        guard points.count >= 4 else { return nil }
        let groups = stride(from: 0, to: points.count, by: 3).map { start in
            points[start..<min(start + 3, points.count)].joined(separator: "، ")
        }
        let content = groups.enumerated().map { "\($0.offset + 1)) \($0.element)" }.joined(separator: "\n")
        return Mnemonic(kind: .chunking, content: content, explanation: L("mnemonic.chunking.groups"), origin: .local)
    }

    static func automatic(for item: LearningItem) -> [Mnemonic] {
        [acronym(for: item), chunking(for: item)].compactMap { $0 }
    }
}
